import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import ts from 'typescript';

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const defaultRepositoryRoot = resolve(scriptDirectory, '../../..');

const GENERATED_HEADER = `/**
 * @generated by packages/shared/scripts/generate-mobile-rpc-contract.mjs.
 * DO NOT EDIT. Run \`pnpm generate:mobile-rpc-contract\` from the repository root.
 */

`;

export const GENERATED_PATHS = {
  local: 'apps/local-app/src/modules/cloud-tunnel/services/mobile-rpc-contract.generated.ts',
  mobile: 'apps/mobile-app/src/services/mobile-rpc-contract.generated.ts',
  bridge: 'apps/devchain-bridge/src/modules/relay/allowed-methods.ts',
};

function canonicalPath(repositoryRoot) {
  return resolve(repositoryRoot, 'packages/shared/src/mobile-rpc-contract/index.ts');
}

async function loadCanonicalContract(repositoryRoot) {
  const sourcePath = canonicalPath(repositoryRoot);
  const contract = await import(pathToFileURL(sourcePath).href);
  const methods = contract.MOBILE_RPC_METHODS;
  const catalog = contract.MOBILE_RPC_CATALOG;

  if (!Array.isArray(methods) || methods.some((method) => typeof method !== 'string')) {
    throw new Error('Canonical MOBILE_RPC_METHODS must be a string tuple');
  }
  if (methods.length !== 42 || new Set(methods).size !== methods.length) {
    throw new Error(
      `Canonical MOBILE_RPC_METHODS must contain 42 unique methods; found ${methods.length}`,
    );
  }
  if (!catalog || typeof catalog !== 'object') {
    throw new Error('Canonical MOBILE_RPC_CATALOG must be an object');
  }

  const catalogMethods = Object.keys(catalog);
  if (
    catalogMethods.length !== methods.length ||
    methods.some((method, index) => catalogMethods[index] !== method)
  ) {
    throw new Error('Canonical method tuple and catalog keys are not ordered identically');
  }

  return methods;
}

function renderBridgeProjection(methods) {
  const methodLines = methods.map((method) => `  ${JSON.stringify(method)},`).join('\n');
  return `${GENERATED_HEADER}export const MOBILE_RPC_METHODS = [
${methodLines}
] as const;

export type MobileRpcMethod = (typeof MOBILE_RPC_METHODS)[number];

export const ALLOWED_METHODS: ReadonlySet<string> = new Set<string>(
  MOBILE_RPC_METHODS,
);

export function isMobileRpcMethod(value: unknown): value is MobileRpcMethod {
  return typeof value === "string" && ALLOWED_METHODS.has(value);
}
`;
}

const METHOD_LITERAL_PATTERN = /["']((?:board|chat|terminal|e2ee)\.[A-Za-z0-9.]+)["']/g;
const METHOD_LITERAL_VALUE_PATTERN = /^(?:board|chat|terminal|e2ee)\.[A-Za-z0-9.]+$/;

function extractMethodLiterals(source) {
  return [...source.matchAll(METHOD_LITERAL_PATTERN)].map((match) => match[1]);
}

function unwrapExpression(expression) {
  let current = expression;
  while (
    ts.isParenthesizedExpression(current) ||
    ts.isAsExpression(current) ||
    ts.isTypeAssertionExpression(current) ||
    ts.isSatisfiesExpression(current) ||
    ts.isNonNullExpression(current)
  ) {
    current = current.expression;
  }
  return current;
}

function propertyNameText(name) {
  if (ts.isIdentifier(name) || ts.isStringLiteralLike(name)) return name.text;
  return null;
}

function methodFromExpression(expression, checker) {
  const current = unwrapExpression(expression);
  if (ts.isStringLiteralLike(current) && METHOD_LITERAL_VALUE_PATTERN.test(current.text)) {
    return current.text;
  }
  const type = checker.getTypeAtLocation(current);
  if (type.isStringLiteral() && METHOD_LITERAL_VALUE_PATTERN.test(type.value)) {
    return type.value;
  }
  return undefined;
}

function resolvedSymbol(identifier, checker) {
  const symbol = checker.getSymbolAtLocation(identifier);
  if (!symbol) return undefined;
  if ((symbol.flags & ts.SymbolFlags.Alias) !== 0) return checker.getAliasedSymbol(symbol);
  return symbol;
}

function isGlobalIdentifier(identifier, checker) {
  const symbol = resolvedSymbol(identifier, checker);
  if (!symbol) return true;
  return !(symbol.declarations ?? []).some(
    (declaration) => !declaration.getSourceFile().isDeclarationFile,
  );
}

function createMobileSourceProgram(sources) {
  const sourceOverrides = new Map(
    sources.map(({ path, source }) => [resolve(path), { path: resolve(path), source }]),
  );
  const compilerOptions = {
    target: ts.ScriptTarget.Latest,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    jsx: ts.JsxEmit.ReactJSX,
    skipLibCheck: true,
    noEmit: true,
  };
  const host = ts.createCompilerHost(compilerOptions, true);
  const defaultGetSourceFile = host.getSourceFile.bind(host);
  host.fileExists = (path) => sourceOverrides.has(resolve(path)) || ts.sys.fileExists(path);
  host.readFile = (path) => sourceOverrides.get(resolve(path))?.source ?? ts.sys.readFile(path);
  host.getSourceFile = (path, languageVersion, onError, shouldCreateNewSourceFile) => {
    const override = sourceOverrides.get(resolve(path));
    if (!override) {
      return defaultGetSourceFile(path, languageVersion, onError, shouldCreateNewSourceFile);
    }
    return ts.createSourceFile(
      override.path,
      override.source,
      languageVersion,
      true,
      override.path.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
    );
  };

  const program = ts.createProgram({
    rootNames: [...sourceOverrides.keys()],
    options: compilerOptions,
    host,
  });
  const sourceFiles = [...sourceOverrides.keys()].map((path) => {
    const sourceFile = program.getSourceFile(path);
    if (!sourceFile) throw new Error(`Mobile RPC source could not be parsed: ${path}`);
    return sourceFile;
  });
  return { checker: program.getTypeChecker(), sourceFiles };
}

function findRelayRequestSymbol(sourceFiles, checker) {
  for (const sourceFile of sourceFiles) {
    for (const statement of sourceFile.statements) {
      if (ts.isFunctionDeclaration(statement) && statement.name?.text === 'relayRequest') {
        return resolvedSymbol(statement.name, checker);
      }
    }
  }
  throw new Error('Mobile relayRequest declaration could not be located');
}

function methodFromDirectRpcFetch(call, checker) {
  const callee = unwrapExpression(call.expression);
  if (
    !ts.isIdentifier(callee) ||
    callee.text !== 'fetch' ||
    !isGlobalIdentifier(callee, checker) ||
    call.arguments.length < 2
  ) {
    return undefined;
  }

  const options = unwrapExpression(call.arguments[1]);
  if (!ts.isObjectLiteralExpression(options)) return undefined;
  const bodyProperty = options.properties.find(
    (property) => ts.isPropertyAssignment(property) && propertyNameText(property.name) === 'body',
  );
  if (!bodyProperty || !ts.isPropertyAssignment(bodyProperty)) return undefined;

  const bodyCall = unwrapExpression(bodyProperty.initializer);
  if (!ts.isCallExpression(bodyCall) || bodyCall.arguments.length === 0) return undefined;
  const bodyCallee = unwrapExpression(bodyCall.expression);
  if (
    !ts.isPropertyAccessExpression(bodyCallee) ||
    !ts.isIdentifier(bodyCallee.expression) ||
    bodyCallee.expression.text !== 'JSON' ||
    !isGlobalIdentifier(bodyCallee.expression, checker) ||
    bodyCallee.name.text !== 'stringify'
  ) {
    return undefined;
  }

  const payload = unwrapExpression(bodyCall.arguments[0]);
  if (!ts.isObjectLiteralExpression(payload)) return undefined;
  const jsonRpcProperty = payload.properties.find(
    (property) =>
      ts.isPropertyAssignment(property) && propertyNameText(property.name) === 'jsonrpc',
  );
  if (!jsonRpcProperty || !ts.isPropertyAssignment(jsonRpcProperty)) return undefined;
  const jsonRpcValue = unwrapExpression(jsonRpcProperty.initializer);
  if (!ts.isStringLiteralLike(jsonRpcValue) || jsonRpcValue.text !== '2.0') return undefined;

  const methodProperty = payload.properties.find(
    (property) => ts.isPropertyAssignment(property) && propertyNameText(property.name) === 'method',
  );
  if (!methodProperty || !ts.isPropertyAssignment(methodProperty)) return undefined;
  return methodFromExpression(methodProperty.initializer, checker);
}

export function extractMobileRpcCallerMethods(sources) {
  const { checker, sourceFiles } = createMobileSourceProgram(sources);
  const relayRequestSymbol = findRelayRequestSymbol(sourceFiles, checker);
  const methods = [];

  for (const sourceFile of sourceFiles) {
    const visit = (node) => {
      if (ts.isCallExpression(node)) {
        const callee = unwrapExpression(node.expression);
        if (
          ts.isIdentifier(callee) &&
          resolvedSymbol(callee, checker) === relayRequestSymbol &&
          node.arguments[2]
        ) {
          const method = methodFromExpression(node.arguments[2], checker);
          if (method) methods.push(method);
        } else {
          const method = methodFromDirectRpcFetch(node, checker);
          if (method) methods.push(method);
        }
      }
      ts.forEachChild(node, visit);
    };
    visit(sourceFile);
  }

  return methods;
}

function compareMethodSets(label, actualMethods, expectedMethods) {
  const actual = new Set(actualMethods);
  const expected = new Set(expectedMethods);
  const missing = expectedMethods.filter((method) => !actual.has(method));
  const extra = [...actual].filter((method) => !expected.has(method)).sort();
  if (missing.length === 0 && extra.length === 0 && actual.size === expected.size) return null;
  return `${label} differs from the canonical catalog (missing: ${missing.join(', ') || 'none'}; extra: ${extra.join(', ') || 'none'})`;
}

async function sourceFilesUnder(root) {
  const files = [];
  async function visit(directory) {
    let entries;
    try {
      entries = await readdir(directory, { withFileTypes: true });
    } catch (error) {
      if (error?.code === 'ENOENT') return;
      throw error;
    }
    for (const entry of entries) {
      const path = resolve(directory, entry.name);
      if (entry.isDirectory()) await visit(path);
      else if (entry.isFile() && /\.[cm]?[jt]sx?$/.test(entry.name)) files.push(path);
    }
  }
  await visit(root);
  return files.sort();
}

export async function findForbiddenMobileSharedImports({
  repositoryRoot = defaultRepositoryRoot,
} = {}) {
  const sourceRoot = resolve(repositoryRoot, 'apps/mobile-app/src');
  const files = await sourceFilesUnder(sourceRoot);
  const forbidden = [];
  const importPattern =
    /(?:\bfrom\s*|\bimport\s*\(|\brequire\s*\(|\bimport\s*)["']@devchain\/shared(?:\/[^"']*)?["']/;

  for (const path of files) {
    const source = await readFile(path, 'utf8');
    if (importPattern.test(source)) {
      forbidden.push(path.slice(repositoryRoot.length + 1));
    }
  }
  return forbidden;
}

export async function verifyCrossAppContract({
  repositoryRoot = defaultRepositoryRoot,
  mobileSourceOverrides = {},
} = {}) {
  const methods = await loadCanonicalContract(repositoryRoot);
  const localPath = resolve(
    repositoryRoot,
    'apps/local-app/src/modules/cloud-tunnel/services/tunnel-handler.service.ts',
  );
  const bridgePath = resolve(repositoryRoot, GENERATED_PATHS.bridge);
  const mobileRelativePaths = [
    'apps/mobile-app/src/services/bridge-client.ts',
    'apps/mobile-app/src/services/e2ee/rpc-session.ts',
    'apps/mobile-app/src/services/viewport/viewport-rpc.ts',
  ];
  const mobilePaths = mobileRelativePaths.map((path) => resolve(repositoryRoot, path));
  const [localSource, bridgeSource, mobileSources, forbiddenImports] = await Promise.all([
    readFile(localPath, 'utf8'),
    readFile(bridgePath, 'utf8'),
    Promise.all(
      mobilePaths.map((path, index) =>
        Object.hasOwn(mobileSourceOverrides, mobileRelativePaths[index])
          ? mobileSourceOverrides[mobileRelativePaths[index]]
          : readFile(path, 'utf8'),
      ),
    ),
    findForbiddenMobileSharedImports({ repositoryRoot }),
  ]);

  const handlerStart = localSource.indexOf('this.handlers = {');
  const handlerEnd = localSource.indexOf('} satisfies MobileRpcHandlerMap;', handlerStart);
  const issues = [];
  if (handlerStart < 0 || handlerEnd < 0) {
    issues.push('Local MobileRpcHandlerMap initializer could not be located');
  } else {
    const localIssue = compareMethodSets(
      'Local RPC handlers',
      extractMethodLiterals(localSource.slice(handlerStart, handlerEnd)),
      methods,
    );
    if (localIssue) issues.push(localIssue);
  }

  const bridgeIssue = compareMethodSets(
    'Bridge RPC admission',
    extractMethodLiterals(bridgeSource),
    methods,
  );
  if (bridgeIssue) issues.push(bridgeIssue);

  const mobileIssue = compareMethodSets(
    'Mobile RPC callers',
    extractMobileRpcCallerMethods(
      mobileSources.map((source, index) => ({ path: mobilePaths[index], source })),
    ),
    methods,
  );
  if (mobileIssue) issues.push(mobileIssue);

  if (forbiddenImports.length > 0) {
    issues.push(
      `Mobile production source imports @devchain/shared: ${forbiddenImports.join(', ')}`,
    );
  }
  return issues;
}

export async function renderGeneratedOutputs({ repositoryRoot = defaultRepositoryRoot } = {}) {
  const [canonicalSource, methods] = await Promise.all([
    readFile(canonicalPath(repositoryRoot), 'utf8'),
    loadCanonicalContract(repositoryRoot),
  ]);
  const fullContract = `${GENERATED_HEADER}${canonicalSource}`;

  return new Map([
    [GENERATED_PATHS.local, fullContract],
    [GENERATED_PATHS.mobile, fullContract],
    [GENERATED_PATHS.bridge, renderBridgeProjection(methods)],
  ]);
}

export async function writeGeneratedOutputs({
  repositoryRoot = defaultRepositoryRoot,
  outputRoot = repositoryRoot,
} = {}) {
  const outputs = await renderGeneratedOutputs({ repositoryRoot });
  const changed = [];

  for (const [relativePath, expected] of outputs) {
    const outputPath = resolve(outputRoot, relativePath);
    let current;
    try {
      current = await readFile(outputPath, 'utf8');
    } catch (error) {
      if (error?.code !== 'ENOENT') throw error;
    }
    if (current === expected) continue;

    await mkdir(dirname(outputPath), { recursive: true });
    await writeFile(outputPath, expected, 'utf8');
    changed.push(relativePath);
  }

  return changed;
}

export async function checkGeneratedOutputs({
  repositoryRoot = defaultRepositoryRoot,
  outputRoot = repositoryRoot,
} = {}) {
  const outputs = await renderGeneratedOutputs({ repositoryRoot });
  const stale = [];

  for (const [relativePath, expected] of outputs) {
    try {
      const current = await readFile(resolve(outputRoot, relativePath), 'utf8');
      if (current !== expected) stale.push(relativePath);
    } catch (error) {
      if (error?.code !== 'ENOENT') throw error;
      stale.push(relativePath);
    }
  }

  return stale;
}

async function main() {
  const mode = process.argv[2];
  if (mode === '--write') {
    const changed = await writeGeneratedOutputs();
    if (changed.length === 0) {
      console.log('Mobile RPC generated outputs are already current.');
    } else {
      console.log(`Generated ${changed.length} mobile RPC output(s):`);
      for (const relativePath of changed) console.log(`- ${relativePath}`);
    }
    return;
  }

  if (mode === '--check') {
    const [stale, verificationIssues] = await Promise.all([
      checkGeneratedOutputs(),
      verifyCrossAppContract(),
    ]);
    if (stale.length > 0 || verificationIssues.length > 0) {
      const staleMessage =
        stale.length > 0
          ? `Mobile RPC generated outputs are stale or missing:\n${stale
              .map((relativePath) => `- ${relativePath}`)
              .join('\n')}\nRun \`pnpm generate:mobile-rpc-contract\` and commit the results.`
          : null;
      throw new Error([staleMessage, ...verificationIssues].filter(Boolean).join('\n'));
    }
    console.log('Mobile RPC generated outputs and cross-app coverage are current.');
    return;
  }

  throw new Error(
    'Usage: node packages/shared/scripts/generate-mobile-rpc-contract.mjs <--write|--check>',
  );
}

const executedPath = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : null;
if (executedPath === import.meta.url) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : error);
    process.exitCode = 1;
  });
}
